import * as T from './vendor/three.module.js';
import {SPORTS,startDescent,stepDescent,finishDescent,FINISH} from './downhill.mjs';
import {createDownhillWorld} from './downhill-world.mjs';
import {stepEnvironment} from './alpine-weather.mjs';
export function createDownhillUI({getState,changed,onClose,sharedRenderer=false,rendererFactory=canvas=>new T.WebGLRenderer({canvas,antialias:true})}){let root=null,renderer=null,world=null,frame=0,last=0,saved=0,running=false,held=new Set(),drag=null,dragSteer=0,notice='',noticeTime=0;
 const c=()=>getState().activities.rides.active,el=id=>root.querySelector('[data-ride="'+id+'"]');
 function clearInput(){held.clear();drag=null;dragSteer=0;}
 function drawPanel(message=''){running=false;clearInput();const a=getState().activities.rides;el('panel').hidden=false;el('panel').innerHTML='<img class="ride-preview" src="assets/portmann/bikepark-reference.webp" alt="Gestaltungsvorlage des alpinen Bikeparks mit Holzschanze"><h2>Bike & Schlitten</h2><p>'+message+'</p><p>Lenken: A/D oder Pfeile · Bremsen: S · Springen: Leertaste. Auf dem Touchscreen lenken oder die Tasten halten.</p><p>Vier gebogene Schanzen mit breiter Landung: Ab 22 km/h trägt dich die mittlere Spur automatisch über die Kante. Vor Kurven und Hindernissen bremsen. Zurücksetzen nach einem Sturz kostet Tempo und Energie.</p>'+Object.entries(SPORTS).map(([id,v])=>'<button data-start="'+id+'">'+v.season+' · '+v.name+'<small>'+a[id].runs+' Abfahrten · Bestwert '+a[id].best+'</small></button>').join('')+(c()?'<button data-resume>Gespeicherte Abfahrt fortsetzen</button><button data-abandon>Abfahrt beenden</button>':'');for(const b of el('panel').querySelectorAll('[data-start]'))b.onclick=()=>{const r=startDescent(getState(),b.dataset.start);if(!r.ok){drawPanel(r.message);return;}changed();begin();};el('panel').querySelector('[data-resume]')?.addEventListener('click',begin);el('panel').querySelector('[data-abandon]')?.addEventListener('click',()=>{getState().activities.rides.active=null;changed();drawPanel('Zurück am Unterstand.');});}
 function fit(){if(!root||!world)return;const w=innerWidth,h=innerHeight;renderer.setSize(w,h,false);world.camera.aspect=w/h;world.camera.updateProjectionMatrix();}
 function begin(){world?.dispose();world=createDownhillWorld(c().mode,{compact:innerWidth<700});fit();el('panel').hidden=true;running=true;last=0;clearInput();}
 function close(){running=false;clearInput();cancelAnimationFrame(frame);world?.dispose();if(!sharedRenderer)renderer?.dispose();root?.remove();root=null;changed();onClose();}
 function tick(t){if(!root)return;const dt=last?Math.min(.05,(t-last)/1000):0;last=t;if(running&&c()){const r=c(),input={steer:(held.has('right')?1:0)-(held.has('left')?1:0)+dragSteer,brake:held.has('brake'),jump:held.has('jump')},event=stepDescent(r,dt,input);stepEnvironment(getState(),dt);if(event){noticeTime=2;notice=({crash:'Sturz! Vor Hindernissen bremsen oder ausweichen.',miss:'Kontrollpunkt verpasst',gate:'Kontrollpunkt geschafft',jump:'Sprung!',ramp:'Rampe getroffen!'})[event.type]||'';el('notice').dataset.tone=['crash','miss'].includes(event.type)?'danger':'success';}noticeTime=Math.max(0,noticeTime-dt);el('notice').textContent=r.countdown>0?'Start in '+Math.ceil(r.countdown):noticeTime>0?notice:'';el('speed').textContent=Math.round(r.speed*3.6)+' km/h · '+Math.round(r.distance)+' / '+FINISH+' m';world.sync(r,getState().environment,dt);renderer.render(world.scene,world.camera);saved+=dt;if(saved>3){saved=0;changed();}if(r.done){const q=finishDescent(getState());changed();drawPanel(q.message+' '+q.score+' Punkte · '+q.time.toFixed(1)+' s · '+q.crashes+' Stürze. Die erste Abfahrt zählt für das Aufgabenbuch.');}}frame=requestAnimationFrame(tick);}
 function open(){if(root)return;root=document.createElement('section');root.className='downhill-overlay';if(sharedRenderer)root.style.background='transparent';root.setAttribute('aria-label','Ego-Abfahrt');root.innerHTML='<canvas data-ride="canvas"></canvas><div class="ride-top"><strong data-ride="speed">Portmann Alp</strong><button data-ride="pause">Pause</button><button data-ride="close">Zur Alp</button></div><p data-ride="notice" role="status"></p><div data-ride="panel" class="ride-panel"></div><div class="ride-controls"><button data-control="left" aria-label="Links lenken">◀</button><button data-control="right" aria-label="Rechts lenken">▶</button><button data-control="brake">Bremsen</button><button data-control="jump">Sprung</button><button data-ride="exit-bottom">Verlassen</button></div>';document.body.appendChild(root);try{renderer=rendererFactory(el('canvas'));renderer.setPixelRatio(Math.min(devicePixelRatio||1,innerWidth<700?1.3:1.7));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;}catch{el('panel').innerHTML='<h2>3D-Abfahrt nicht verfügbar</h2><p>Die zusätzliche 3D-Ansicht konnte nicht starten. Dein Spielstand bleibt erhalten.</p>';el('close').onclick=close;return;}el('close').onclick=close;el('exit-bottom').onclick=close;el('pause').onclick=()=>{changed();drawPanel('Abfahrt pausiert und gespeichert.');};for(const b of root.querySelectorAll('[data-control]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture?.(e.pointerId);held.add(b.dataset.control);};for(const type of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>held.delete(b.dataset.control));}const canvas=el('canvas');canvas.onpointerdown=e=>{drag={id:e.pointerId,x:e.clientX};canvas.setPointerCapture?.(e.pointerId);};canvas.onpointermove=e=>{if(drag?.id===e.pointerId)dragSteer=Math.max(-1,Math.min(1,(e.clientX-drag.x)/90));};for(const type of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>{drag=null;dragSteer=0;});drawPanel(c()?'Deine gespeicherte Abfahrt wartet.':'Wähle deine Abfahrt. Helm und Sportgerät werden gestellt.');frame=requestAnimationFrame(tick);}
 const key=e=>({ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowDown:'brake',KeyS:'brake',Space:'jump'})[e.code];globalThis.window?.addEventListener?.('keydown',e=>{if(!root)return;const k=key(e);if(k){e.preventDefault();held.add(k);}if(e.code==='Escape'){changed();drawPanel('Pause');}});globalThis.window?.addEventListener?.('keyup',e=>{if(root)held.delete(key(e));});globalThis.window?.addEventListener?.('resize',fit);globalThis.window?.addEventListener?.('blur',()=>{if(root){changed();drawPanel('Pause');}});return{open,close,get active(){return !!root;}};}
